import * as path from 'node:path';
import * as cdk from 'aws-cdk-lib';
import { Asset } from 'aws-cdk-lib/aws-s3-assets';
import type { Construct } from 'constructs';

/**
 * Serverless Fraud Detection Platform
 *
 * Generated by AWS Architecture Advisor. Deploys exactly the same resources as
 * ../infrastructure/template.yaml: one CfnResource per resource, with the same logical IDs.
 * To evolve it, replace a CfnResource with the matching higher-level construct
 * (for example aws-cdk-lib/aws-dynamodb Table) and run `npx cdk diff` to check the change.
 */
export class AppStack extends cdk.Stack {
  constructor(scope: Construct, id: string, props?: cdk.StackProps) {
    super(scope, id, props);
    this.templateOptions.templateFormatVersion = '2010-09-09';

    // Transactions API: HTTP API with two routes: POST /transactions for ingestion and GET /flagged for querying flagged transactions with explanations
    const transactionsApi = new cdk.CfnResource(this, "TransactionsApi", {
      type: "AWS::ApiGatewayV2::Api",
      properties: {
        Name: cdk.Fn.sub("${AWS::StackName}-transactions-api"),
        ProtocolType: "HTTP",
        CorsConfiguration: {
          AllowOrigins: [
            "*",
          ],
          AllowMethods: [
            "GET",
            "POST",
            "PUT",
            "PATCH",
            "DELETE",
            "OPTIONS",
          ],
          AllowHeaders: [
            "authorization",
            "content-type",
          ],
        },
      },
    });

    // AWS::ApiGatewayV2::Stage
    const transactionsApiStage = new cdk.CfnResource(this, "TransactionsApiStage", {
      type: "AWS::ApiGatewayV2::Stage",
      properties: {
        ApiId: transactionsApi.ref,
        StageName: "$default",
        AutoDeploy: true,
      },
    });

    // AWS::SQS::Queue
    const processingQueueDlq = new cdk.CfnResource(this, "ProcessingQueueDlq", {
      type: "AWS::SQS::Queue",
      properties: {
        SqsManagedSseEnabled: true,
        MessageRetentionPeriod: 1209600,
      },
    });

    // Processing Queue: Decouples ingestion from scoring, provides back-pressure and retry semantics with a 3-retry redrive policy to the DLQ
    const processingQueue = new cdk.CfnResource(this, "ProcessingQueue", {
      type: "AWS::SQS::Queue",
      properties: {
        SqsManagedSseEnabled: true,
        VisibilityTimeout: 180,
        RedrivePolicy: {
          deadLetterTargetArn: processingQueueDlq.getAtt("Arn"),
          maxReceiveCount: 5,
        },
      },
    });

    // AWS::SQS::Queue
    const deadLetterQueueDlq = new cdk.CfnResource(this, "DeadLetterQueueDlq", {
      type: "AWS::SQS::Queue",
      properties: {
        SqsManagedSseEnabled: true,
        MessageRetentionPeriod: 1209600,
      },
    });

    // Dead Letter Queue: Captures messages that fail scoring 3 times for manual investigation; triggers a CloudWatch alarm when non-empty
    const deadLetterQueue = new cdk.CfnResource(this, "DeadLetterQueue", {
      type: "AWS::SQS::Queue",
      properties: {
        SqsManagedSseEnabled: true,
        VisibilityTimeout: 180,
        RedrivePolicy: {
          deadLetterTargetArn: deadLetterQueueDlq.getAtt("Arn"),
          maxReceiveCount: 5,
        },
      },
    });

    // Transactions Data Lake: Stores all transaction data partitioned by date (year/month/day) in Parquet format for efficient Athena queries. Separate prefixe
    const transactionsBucket = new cdk.CfnResource(this, "TransactionsBucket", {
      type: "AWS::S3::Bucket",
      properties: {
        PublicAccessBlockConfiguration: {
          BlockPublicAcls: true,
          BlockPublicPolicy: true,
          IgnorePublicAcls: true,
          RestrictPublicBuckets: true,
        },
        BucketEncryption: {
          ServerSideEncryptionConfiguration: [
            {
              ServerSideEncryptionByDefault: {
                SSEAlgorithm: "AES256",
              },
            },
          ],
        },
        OwnershipControls: {
          Rules: [
            {
              ObjectOwnership: "BucketOwnerEnforced",
            },
          ],
        },
      },
    });

    // Flagged Transactions Table: Stores flagged transactions with attributes: transactionId (PK), timestamp (SK), riskScore, rulesFired, mlScore, explanation,
    const flaggedTable = new cdk.CfnResource(this, "FlaggedTable", {
      type: "AWS::DynamoDB::Table",
      properties: {
        BillingMode: "PAY_PER_REQUEST",
        AttributeDefinitions: [
          {
            AttributeName: "pk",
            AttributeType: "S",
          },
          {
            AttributeName: "sk",
            AttributeType: "S",
          },
        ],
        KeySchema: [
          {
            AttributeName: "pk",
            KeyType: "HASH",
          },
          {
            AttributeName: "sk",
            KeyType: "RANGE",
          },
        ],
        PointInTimeRecoverySpecification: {
          PointInTimeRecoveryEnabled: true,
        },
        SSESpecification: {
          SSEEnabled: true,
        },
      },
    });

    // Fraud Alerts Topic: Publishes high-risk transaction alerts (riskScore > 0.85) to email subscribers. Message includes transaction ID, amount, merchant, ri
    const alertsTopic = new cdk.CfnResource(this, "AlertsTopic", {
      type: "AWS::SNS::Topic",
      properties: {},
    });

    // AWS::IAM::Role
    const scoringFunctionRole = new cdk.CfnResource(this, "ScoringFunctionRole", {
      type: "AWS::IAM::Role",
      properties: {
        AssumeRolePolicyDocument: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Principal: {
                Service: "lambda.amazonaws.com",
              },
              Action: "sts:AssumeRole",
            },
          ],
        },
        ManagedPolicyArns: [
          cdk.Fn.sub("arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"),
        ],
        Policies: [
          {
            PolicyName: "resource-access",
            PolicyDocument: {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "sqs:ReceiveMessage",
                    "sqs:DeleteMessage",
                    "sqs:GetQueueAttributes",
                  ],
                  Resource: processingQueue.getAtt("Arn"),
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:GetObject",
                    "s3:PutObject",
                    "s3:DeleteObject",
                  ],
                  Resource: cdk.Fn.sub("${TransactionsBucket.Arn}/*"),
                },
                {
                  Effect: "Allow",
                  Action: [
                    "s3:ListBucket",
                  ],
                  Resource: transactionsBucket.getAtt("Arn"),
                },
                {
                  Effect: "Allow",
                  Action: [
                    "dynamodb:GetItem",
                    "dynamodb:PutItem",
                    "dynamodb:UpdateItem",
                    "dynamodb:DeleteItem",
                    "dynamodb:Query",
                    "dynamodb:Scan",
                    "dynamodb:BatchGetItem",
                    "dynamodb:BatchWriteItem",
                  ],
                  Resource: [
                    flaggedTable.getAtt("Arn"),
                    cdk.Fn.sub("${FlaggedTable.Arn}/index/*"),
                  ],
                },
                {
                  Effect: "Allow",
                  Action: [
                    "sns:Publish",
                  ],
                  Resource: alertsTopic.ref,
                },
                {
                  Effect: "Allow",
                  Action: [
                    "lambda:InvokeFunction",
                  ],
                  Resource: cdk.Fn.sub("arn:${AWS::Partition}:lambda:${AWS::Region}:${AWS::AccountId}:function:${AWS::StackName}-explainer-function"),
                },
              ],
            },
          },
        ],
      },
    });

    // Fraud Scoring Engine: Runs rule-based checks (amount threshold, velocity per card in 1h window, geo-impossible travel) then scores with an Isolation Fore
    const scoringFunctionCode = new Asset(this, "ScoringFunctionCode", { path: path.join(__dirname, '..', '..', 'build', "scoring-function") });
    const scoringFunction = new cdk.CfnResource(this, "ScoringFunction", {
      type: "AWS::Lambda::Function",
      properties: {
        Description: "Runs rule-based checks (amount threshold, velocity per card in 1h window, geo-impossible travel) then scores with an Isolation Forest model packaged as a Lambda layer. Writes raw+scored data to S3, flagged transactions to DynamoDB, high-risk alerts to SNS,",
        Runtime: "nodejs22.x",
        Handler: "index.handler",
        Architectures: [
          "arm64",
        ],
        MemorySize: 1024,
        Timeout: 30,
        Role: scoringFunctionRole.getAtt("Arn"),
        Code: { S3Bucket: scoringFunctionCode.s3BucketName, S3Key: scoringFunctionCode.s3ObjectKey },
        Environment: {
          Variables: {
            TRANSACTIONS_BUCKET_BUCKET_NAME: transactionsBucket.ref,
            FLAGGED_TABLE_TABLE_NAME: flaggedTable.ref,
            ALERTS_TOPIC_TOPIC_ARN: alertsTopic.ref,
            EXPLAINER_FUNCTION_FUNCTION_NAME: cdk.Fn.sub("${AWS::StackName}-explainer-function"),
          },
        },
      },
    });

    // AWS::Lambda::EventSourceMapping
    const processingQueueScoringFunctionTrigger = new cdk.CfnResource(this, "ProcessingQueueScoringFunctionTrigger", {
      type: "AWS::Lambda::EventSourceMapping",
      properties: {
        EventSourceArn: processingQueue.getAtt("Arn"),
        FunctionName: scoringFunction.ref,
        BatchSize: 10,
      },
    });

    // AWS::IAM::Role
    const ingestFunctionRole = new cdk.CfnResource(this, "IngestFunctionRole", {
      type: "AWS::IAM::Role",
      properties: {
        AssumeRolePolicyDocument: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Principal: {
                Service: "lambda.amazonaws.com",
              },
              Action: "sts:AssumeRole",
            },
          ],
        },
        ManagedPolicyArns: [
          cdk.Fn.sub("arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"),
        ],
        Policies: [
          {
            PolicyName: "resource-access",
            PolicyDocument: {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "sqs:SendMessage",
                  ],
                  Resource: processingQueue.getAtt("Arn"),
                },
              ],
            },
          },
        ],
      },
    });

    // Transaction Ingest: Validates incoming transaction payload (card, amount, merchant, location, timestamp), assigns a transaction ID, and sends it to the p
    const ingestFunctionCode = new Asset(this, "IngestFunctionCode", { path: path.join(__dirname, '..', '..', 'build', "ingest-function") });
    const ingestFunction = new cdk.CfnResource(this, "IngestFunction", {
      type: "AWS::Lambda::Function",
      properties: {
        Description: "Validates incoming transaction payload (card, amount, merchant, location, timestamp), assigns a transaction ID, and sends it to the processing queue",
        Runtime: "nodejs22.x",
        Handler: "index.handler",
        Architectures: [
          "arm64",
        ],
        MemorySize: 256,
        Timeout: 10,
        Role: ingestFunctionRole.getAtt("Arn"),
        Code: { S3Bucket: ingestFunctionCode.s3BucketName, S3Key: ingestFunctionCode.s3ObjectKey },
        Environment: {
          Variables: {
            PROCESSING_QUEUE_QUEUE_URL: processingQueue.ref,
          },
        },
      },
    });

    // AWS::Logs::LogGroup
    const ingestFunctionLogs = new cdk.CfnResource(this, "IngestFunctionLogs", {
      type: "AWS::Logs::LogGroup",
      properties: {
        LogGroupName: cdk.Fn.sub("/aws/lambda/${IngestFunction}"),
        RetentionInDays: 14,
      },
    });

    // AWS::Logs::LogGroup
    const scoringFunctionLogs = new cdk.CfnResource(this, "ScoringFunctionLogs", {
      type: "AWS::Logs::LogGroup",
      properties: {
        LogGroupName: cdk.Fn.sub("/aws/lambda/${ScoringFunction}"),
        RetentionInDays: 14,
      },
    });

    // AWS::IAM::Role
    const explainerFunctionRole = new cdk.CfnResource(this, "ExplainerFunctionRole", {
      type: "AWS::IAM::Role",
      properties: {
        AssumeRolePolicyDocument: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Principal: {
                Service: "lambda.amazonaws.com",
              },
              Action: "sts:AssumeRole",
            },
          ],
        },
        ManagedPolicyArns: [
          cdk.Fn.sub("arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"),
        ],
        Policies: [
          {
            PolicyName: "resource-access",
            PolicyDocument: {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "dynamodb:GetItem",
                    "dynamodb:PutItem",
                    "dynamodb:UpdateItem",
                    "dynamodb:DeleteItem",
                    "dynamodb:Query",
                    "dynamodb:Scan",
                    "dynamodb:BatchGetItem",
                    "dynamodb:BatchWriteItem",
                  ],
                  Resource: [
                    flaggedTable.getAtt("Arn"),
                    cdk.Fn.sub("${FlaggedTable.Arn}/index/*"),
                  ],
                },
              ],
            },
          },
        ],
      },
    });

    // Bedrock Explainer: Invoked asynchronously for flagged transactions. Calls Bedrock Claude 3 Haiku with the transaction context and scoring details to gene
    const explainerFunctionCode = new Asset(this, "ExplainerFunctionCode", { path: path.join(__dirname, '..', '..', 'build', "explainer-function") });
    const explainerFunction = new cdk.CfnResource(this, "ExplainerFunction", {
      type: "AWS::Lambda::Function",
      properties: {
        FunctionName: cdk.Fn.sub("${AWS::StackName}-explainer-function"),
        Description: "Invoked asynchronously for flagged transactions. Calls Bedrock Claude 3 Haiku with the transaction context and scoring details to generate a plain-English fraud explanation. Enforces a monthly call cap via a DynamoDB counter. Updates the flagged table with",
        Runtime: "nodejs22.x",
        Handler: "index.handler",
        Architectures: [
          "arm64",
        ],
        MemorySize: 256,
        Timeout: 30,
        Role: explainerFunctionRole.getAtt("Arn"),
        Code: { S3Bucket: explainerFunctionCode.s3BucketName, S3Key: explainerFunctionCode.s3ObjectKey },
        Environment: {
          Variables: {
            FLAGGED_TABLE_TABLE_NAME: flaggedTable.ref,
          },
        },
      },
    });

    // AWS::Logs::LogGroup
    const explainerFunctionLogs = new cdk.CfnResource(this, "ExplainerFunctionLogs", {
      type: "AWS::Logs::LogGroup",
      properties: {
        LogGroupName: cdk.Fn.sub("/aws/lambda/${ExplainerFunction}"),
        RetentionInDays: 14,
      },
    });

    // AWS::IAM::Role
    const queryFunctionRole = new cdk.CfnResource(this, "QueryFunctionRole", {
      type: "AWS::IAM::Role",
      properties: {
        AssumeRolePolicyDocument: {
          Version: "2012-10-17",
          Statement: [
            {
              Effect: "Allow",
              Principal: {
                Service: "lambda.amazonaws.com",
              },
              Action: "sts:AssumeRole",
            },
          ],
        },
        ManagedPolicyArns: [
          cdk.Fn.sub("arn:${AWS::Partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"),
        ],
        Policies: [
          {
            PolicyName: "resource-access",
            PolicyDocument: {
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Action: [
                    "dynamodb:GetItem",
                    "dynamodb:PutItem",
                    "dynamodb:UpdateItem",
                    "dynamodb:DeleteItem",
                    "dynamodb:Query",
                    "dynamodb:Scan",
                    "dynamodb:BatchGetItem",
                    "dynamodb:BatchWriteItem",
                  ],
                  Resource: [
                    flaggedTable.getAtt("Arn"),
                    cdk.Fn.sub("${FlaggedTable.Arn}/index/*"),
                  ],
                },
              ],
            },
          },
        ],
      },
    });

    // Query Flagged Transactions: Handles GET /flagged endpoint with optional query parameters (minRiskScore, startDate, endDate, merchantId). Returns paginate
    const queryFunctionCode = new Asset(this, "QueryFunctionCode", { path: path.join(__dirname, '..', '..', 'build', "query-function") });
    const queryFunction = new cdk.CfnResource(this, "QueryFunction", {
      type: "AWS::Lambda::Function",
      properties: {
        Description: "Handles GET /flagged endpoint with optional query parameters (minRiskScore, startDate, endDate, merchantId). Returns paginated flagged transactions with their Bedrock explanations from DynamoDB",
        Runtime: "nodejs22.x",
        Handler: "index.handler",
        Architectures: [
          "arm64",
        ],
        MemorySize: 256,
        Timeout: 10,
        Role: queryFunctionRole.getAtt("Arn"),
        Code: { S3Bucket: queryFunctionCode.s3BucketName, S3Key: queryFunctionCode.s3ObjectKey },
        Environment: {
          Variables: {
            FLAGGED_TABLE_TABLE_NAME: flaggedTable.ref,
          },
        },
      },
    });

    // AWS::Logs::LogGroup
    const queryFunctionLogs = new cdk.CfnResource(this, "QueryFunctionLogs", {
      type: "AWS::Logs::LogGroup",
      properties: {
        LogGroupName: cdk.Fn.sub("/aws/lambda/${QueryFunction}"),
        RetentionInDays: 14,
      },
    });

    // AWS::ApiGatewayV2::Integration
    const transactionsApiIngestFunctionIntegration = new cdk.CfnResource(this, "TransactionsApiIngestFunctionIntegration", {
      type: "AWS::ApiGatewayV2::Integration",
      properties: {
        ApiId: transactionsApi.ref,
        IntegrationType: "AWS_PROXY",
        IntegrationUri: ingestFunction.getAtt("Arn"),
        PayloadFormatVersion: "2.0",
      },
    });

    // AWS::ApiGatewayV2::Route
    const transactionsApiIngestFunctionRoute = new cdk.CfnResource(this, "TransactionsApiIngestFunctionRoute", {
      type: "AWS::ApiGatewayV2::Route",
      properties: {
        ApiId: transactionsApi.ref,
        RouteKey: "ANY /ingest-function/{proxy+}",
        Target: cdk.Fn.sub("integrations/${TransactionsApiIngestFunctionIntegration}"),
      },
    });

    // AWS::Lambda::Permission
    const ingestFunctionTransactionsApiPermission = new cdk.CfnResource(this, "IngestFunctionTransactionsApiPermission", {
      type: "AWS::Lambda::Permission",
      properties: {
        FunctionName: ingestFunction.getAtt("Arn"),
        Action: "lambda:InvokeFunction",
        Principal: "apigateway.amazonaws.com",
        SourceArn: cdk.Fn.sub("arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${TransactionsApi}/*"),
      },
    });

    // AWS::ApiGatewayV2::Integration
    const transactionsApiQueryFunctionIntegration = new cdk.CfnResource(this, "TransactionsApiQueryFunctionIntegration", {
      type: "AWS::ApiGatewayV2::Integration",
      properties: {
        ApiId: transactionsApi.ref,
        IntegrationType: "AWS_PROXY",
        IntegrationUri: queryFunction.getAtt("Arn"),
        PayloadFormatVersion: "2.0",
      },
    });

    // AWS::ApiGatewayV2::Route
    const transactionsApiQueryFunctionRoute = new cdk.CfnResource(this, "TransactionsApiQueryFunctionRoute", {
      type: "AWS::ApiGatewayV2::Route",
      properties: {
        ApiId: transactionsApi.ref,
        RouteKey: "ANY /query-function/{proxy+}",
        Target: cdk.Fn.sub("integrations/${TransactionsApiQueryFunctionIntegration}"),
      },
    });

    // AWS::Lambda::Permission
    const queryFunctionTransactionsApiPermission = new cdk.CfnResource(this, "QueryFunctionTransactionsApiPermission", {
      type: "AWS::Lambda::Permission",
      properties: {
        FunctionName: queryFunction.getAtt("Arn"),
        Action: "lambda:InvokeFunction",
        Principal: "apigateway.amazonaws.com",
        SourceArn: cdk.Fn.sub("arn:${AWS::Partition}:execute-api:${AWS::Region}:${AWS::AccountId}:${TransactionsApi}/*"),
      },
    });

    // AWS::CloudWatch::Alarm
    const ingestFunctionErrorsAlarm = new cdk.CfnResource(this, "IngestFunctionErrorsAlarm", {
      type: "AWS::CloudWatch::Alarm",
      properties: {
        AlarmDescription: "Errors in Transaction Ingest",
        Namespace: "AWS/Lambda",
        MetricName: "Errors",
        Dimensions: [
          {
            Name: "FunctionName",
            Value: ingestFunction.ref,
          },
        ],
        Statistic: "Sum",
        Period: 300,
        EvaluationPeriods: 1,
        Threshold: 1,
        ComparisonOperator: "GreaterThanOrEqualToThreshold",
        TreatMissingData: "notBreaching",
      },
    });

    // AWS::CloudWatch::Alarm
    const scoringFunctionErrorsAlarm = new cdk.CfnResource(this, "ScoringFunctionErrorsAlarm", {
      type: "AWS::CloudWatch::Alarm",
      properties: {
        AlarmDescription: "Errors in Fraud Scoring Engine",
        Namespace: "AWS/Lambda",
        MetricName: "Errors",
        Dimensions: [
          {
            Name: "FunctionName",
            Value: scoringFunction.ref,
          },
        ],
        Statistic: "Sum",
        Period: 300,
        EvaluationPeriods: 1,
        Threshold: 1,
        ComparisonOperator: "GreaterThanOrEqualToThreshold",
        TreatMissingData: "notBreaching",
      },
    });

    // AWS::CloudWatch::Alarm
    const explainerFunctionErrorsAlarm = new cdk.CfnResource(this, "ExplainerFunctionErrorsAlarm", {
      type: "AWS::CloudWatch::Alarm",
      properties: {
        AlarmDescription: "Errors in Bedrock Explainer",
        Namespace: "AWS/Lambda",
        MetricName: "Errors",
        Dimensions: [
          {
            Name: "FunctionName",
            Value: explainerFunction.ref,
          },
        ],
        Statistic: "Sum",
        Period: 300,
        EvaluationPeriods: 1,
        Threshold: 1,
        ComparisonOperator: "GreaterThanOrEqualToThreshold",
        TreatMissingData: "notBreaching",
      },
    });

    // AWS::CloudWatch::Alarm
    const queryFunctionErrorsAlarm = new cdk.CfnResource(this, "QueryFunctionErrorsAlarm", {
      type: "AWS::CloudWatch::Alarm",
      properties: {
        AlarmDescription: "Errors in Query Flagged Transactions",
        Namespace: "AWS/Lambda",
        MetricName: "Errors",
        Dimensions: [
          {
            Name: "FunctionName",
            Value: queryFunction.ref,
          },
        ],
        Statistic: "Sum",
        Period: 300,
        EvaluationPeriods: 1,
        Threshold: 1,
        ComparisonOperator: "GreaterThanOrEqualToThreshold",
        TreatMissingData: "notBreaching",
      },
    });

    new cdk.CfnOutput(this, "TransactionsApiUrl", { value: cdk.Token.asString(transactionsApi.getAtt("ApiEndpoint")) });
    new cdk.CfnOutput(this, "ProcessingQueueQueueUrl", { value: processingQueue.ref });
    new cdk.CfnOutput(this, "DeadLetterQueueQueueUrl", { value: deadLetterQueue.ref });
    new cdk.CfnOutput(this, "TransactionsBucketBucketName", { value: transactionsBucket.ref });
    new cdk.CfnOutput(this, "FlaggedTableTableName", { value: flaggedTable.ref });
    new cdk.CfnOutput(this, "AlertsTopicTopicArn", { value: alertsTopic.ref });
  }
}
